svg.script:
(function () {
  const svg = document.documentElement;
  const controls = document.getElementById("svg-controls");
  const btnPrev = document.getElementById("btn-prev");
  const btnToggle = document.getElementById("btn-toggle");
  const btnNext = document.getElementById("btn-next");
  const icoPause = document.getElementById("ico-pause");
  const icoPlay = document.getElementById("ico-play");
  const statusTxt = document.getElementById("ctrl-status");
  if (!controls || !btnPrev || !btnToggle || !btnNext) return;

  const DUR_SEC = 36;
  const DUR_MS = DUR_SEC * 1000;
  const STEP_TIMES = [1.50, 4.50, 7.50, 10.50, 13.50, 16.50, 19.50, 22.50, 25.50, 28.50, 31.50, 34.50];
  const N = STEP_TIMES.length;

  let paused = false;
  let currentStep = 0;

  controls.removeAttribute("display");

  function getAnims() {
    return typeof svg.getAnimations === "function"
      ? svg.getAnimations({ subtree: true })
      : [];
  }

  function inferCurrentStep() {
    const anims = getAnims();
    if (anims.length > 0 && typeof anims[0].currentTime === "number") {
      const t = ((anims[0].currentTime % DUR_MS) + DUR_MS) % DUR_MS;
      return Math.min(N - 1, Math.floor((t / DUR_MS) * N));
    }
    return currentStep;
  }

  function updateUi() {
    if (icoPause) icoPause.setAttribute("display", paused ? "none" : "inline");
    if (icoPlay) icoPlay.setAttribute("display", paused ? "inline" : "none");
    statusTxt.textContent = paused
      ? "Pausa · Paso " + (currentStep + 1) + "/" + N
      : "Auto · ←/→/Espacio";
  }

  function seekStep(idx) {
    currentStep = ((idx % N) + N) % N;
    paused = true;
    const sec = STEP_TIMES[currentStep];
    const anims = getAnims();
    if (anims.length > 0) {
      for (const a of anims) {
        a.pause();
        a.currentTime = sec * 1000;
      }
    } else {
      svg.style.setProperty("--play-state", "paused");
      svg.style.setProperty("--anim-delay", "-" + sec + "s");
    }
    updateUi();
  }

  function togglePlay() {
    const anims = getAnims();
    if (!paused) {
      currentStep = inferCurrentStep();
      paused = true;
      if (anims.length > 0) {
        for (const a of anims) a.pause();
      } else {
        svg.style.setProperty("--play-state", "paused");
      }
    } else {
      paused = false;
      if (anims.length > 0) {
        for (const a of anims) a.play();
      } else {
        svg.style.setProperty("--play-state", "running");
      }
    }
    updateUi();
  }

  btnToggle.addEventListener("click", togglePlay);
  btnPrev.addEventListener("click", function () {
    const base = paused ? currentStep : inferCurrentStep();
    seekStep(base - 1);
  });
  btnNext.addEventListener("click", function () {
    const base = paused ? currentStep : inferCurrentStep();
    seekStep(base + 1);
  });

  document.querySelectorAll("[data-step]").forEach(function (el) {
    el.classList.add("step-clickable");
    el.addEventListener("click", function () {
      seekStep(parseInt(el.getAttribute("data-step"), 10));
    });
  });

  window.addEventListener("keydown", function (e) {
    if (e.key === " " || e.code === "Space") {
      e.preventDefault();
      togglePlay();
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      const base = paused ? currentStep : inferCurrentStep();
      seekStep(base - 1);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      const base = paused ? currentStep : inferCurrentStep();
      seekStep(base + 1);
    }
  });

  updateUi();
})();
